const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const mountFuji = ee.Geometry.Point([138.7278, 35.3606]); // Mount Fuji coordinates
  const buffer = mountFuji.buffer(5000); // 5km buffer around Mount Fuji

  // Function to calculate NDSI
  function calculateNDSI(image) {
    const ndsi = image.normalizedDifference(['B3', 'B6']).rename('NDSI');
    return image.addBands(ndsi);
  }

  // Function to process December data for a given year
  async function processDecember(year, collectionId) {
    const startDate = ee.Date.fromYMD(year, 11, 1); // December 1st
    const endDate = ee.Date.fromYMD(year + 1, 0, 1); // January 1st next year

    let collection = ee.ImageCollection(collectionId)
      .filterBounds(buffer)
      .filterDate(startDate, endDate)
      .map(calculateNDSI)
      .select(['NDSI']);

    const count = collection.size().getInfo();
    if (count === 0) return null;

    // Calculate mean NDSI
    const meanImage = collection.mean();
    const stats = meanImage.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: buffer,
      scale: 1000,
      maxPixels: 1e9
    });

    const meanNDSI = stats.get('NDSI').getInfo();
    const pixelCount = meanImage.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: buffer,
      scale: 1000,
      maxPixels: 1e9
    }).get('NDSI').getInfo();

    return {year, meanNDSI, pixelCount, images: count};
  }

  // 2. Process December 2020 (Landsat 8)
  const ndsi2020 = await processDecember(2020, 'LANDSAT/LC08/C02/T1_L2');
  if (!ndsi2020) {
    console.log("No data for December 2020");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Process December 2005-2015
  const historicalNDSI = [];
  for (let year = 2005; year <= 2015; year++) {
    let collectionId;
    if (year <= 2011) {
      collectionId = 'LANDSAT/LE07/C02/T1_L2'; // Landsat 7
    } else {
      collectionId = 'LANDSAT/LC08/C02/T1_L2'; // Landsat 8
    }

    const result = await processDecember(year, collectionId);
    if (result) {
      historicalNDSI.push(result);
    }
  }

  // Check if we have historical data
  if (historicalNDSI.length === 0) {
    console.log("No historical data found (2005-2015)");
    console.log("<answer>C1</answer>");
    return;
  }

  // 4. Validation checks
  if (ndsi2020.pixelCount === 0) {
    console.log("No valid pixels for 2020");
    console.log("<answer>C2</answer>");
    return;
  }

  // Check for invalid NDSI values
  if (ndsi2020.meanNDSI === null || isNaN(ndsi2020.meanNDSI) || 
      ndsi2020.meanNDSI < -1 || ndsi2020.meanNDSI > 1) {
    console.log("Invalid NDSI value for 2020");
    console.log("<answer>C3</answer>");
    return;
  }

  // 5. Compare with historical data
  console.log(`December 2020: NDSI=${ndsi2020.meanNDSI.toFixed(3)}, Images=${ndsi2020.images}`);

  let allLower = true;
  for (const hist of historicalNDSI) {
    console.log(`December ${hist.year}: NDSI=${hist.meanNDSI.toFixed(3)}, Images=${hist.images}`);

    if (hist.meanNDSI === null || isNaN(hist.meanNDSI)) {
      console.log("Invalid historical NDSI value");
      console.log("<answer>C3</answer>");
      return;
    }

    if (ndsi2020.meanNDSI >= hist.meanNDSI) {
      allLower = false;
    }
  }

  // 6. Final answer
  if (allLower) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
